import { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import { get } from 'lodash/object'
import { isEmpty } from 'lodash/lang'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { Container, CustomText, TermsCondition } from '../../../../components'
import customerActions from '../../../../redux/customer/actions'
import { CustPolicySummaryStyle, SummaryBodyStyle } from './index.style'
import StepsHeader from '../../../../components/StepsHeader'
import { LANG_STRINGS } from '../../../../lang'
import PaymentTime from './components/PaymentTime'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { getVehicleType } from '../../../../helpers/data'
import { Row } from '../../../../commonStyle/index.style'
import PolicyAmountDistribution from '../../../../components/AmountDistribution'
import Expand from '../../../../components/Expand'
import {
  formatMoney,
  validatePaymentTimeCounter,
} from '../../../../helpers/utility'
import { USAGE } from '../../../../constants/appConstants'
import { REDIRECT_PAYMENT_STATUS } from '../../../../constants/payment'
import SingleImgContainer from '../../../../components/SingleImgContainer'
import PdfContainer from '../../../../components/PdfContainer'
import { ACCESSORY } from '../../../../constants/quoatation'
import PolicyInfo from '../../../../components/PolicyCancelledRejectionInfo'
import QuickViewPackageCard from '../../../../components/QuickViewPackageCard'
import ZoomImg from '../../../../components/zoomImg'
import TermsNConditionModal from '../../../Private/Application/components/TermsNConditionModal'

const {
  getCustomerPolicy,
  submitCustomerPolicy,
  resetCustomerStore,
  getCustomerDraftDetailsReq,
  completeCustomerDraftQuoteReq,
} = customerActions

class CustomerPolicySummary extends Component {
  constructor(props) {
    super(props)
    this.state = {
      isValidateTime: true,
      showTncModal: false,
      policyQuotation: {},
      step: 2,
    }
    this.validityCheck = false
    this.isRenewalFlow = window.location.href.includes('renewal')
  }

  componentDidMount() {
    this.policyId = get(this.props, 'match.params.policyId', '')
    this.draftQuoteId = get(this.props, 'match.params.draftQuoteId', '')

    if (this.policyId) {
      // this getting the details for the customer Data
      this.setState({
        step: get(this.props, 'match.params.step', ''),
      })
      this.props.getCustomerPolicy(this.policyId)
    } else if (this.draftQuoteId) {
      this.props.getCustomerDraftDetailsReq({
        draftQuoteId: this.props.match.params.draftQuoteId,
      })
    }
  }

  componentWillReceiveProps(nextProps) {
    const {
      submitCustomerPolicyStatus,
      submitPolicyError,
      resetCustomerStore,
      customerPolicy = {},
      getCustomerDraftQuoteDetailStatus,
      getCustomerDraftQuoteDetailData,
      customerPolicyDataStatus,
      completeCustomerDraftStatus,
      completeCustomerDraftData,
    } = nextProps

    if (submitCustomerPolicyStatus === 'success') {
      this.props.history.push({
        pathname: `/customer/payment/${customerPolicy?.product_key}/${this.props.match.params.policyId}`,
      })
      resetCustomerStore(['submitCustomerPolicyStatus'])
    }

    if (
      submitPolicyError &&
      submitCustomerPolicyStatus &&
      submitCustomerPolicyStatus !== 'success'
    ) {
      // show error to customer if form not submitted
      NotificationManager.error(submitCustomerPolicyStatus)
      resetCustomerStore(['submitCustomerPolicyStatus'])
    }

    if (!this.validityCheck && customerPolicy.application_date) {
      this.validityCheck = true
      this.setState({
        isValidateTime: validatePaymentTimeCounter(
          customerPolicy.application_date
        ),
      })
    }

    if (customerPolicyDataStatus === 'success') {
      this.setState({
        policyQuotation: customerPolicy,
      })
      resetCustomerStore(['customerPolicyDataStatus'])
    }

    if (completeCustomerDraftStatus === 'success') {
      this.props.history.push({
        pathname: `/customer/payment/${customerPolicy?.product_key}/${completeCustomerDraftData.id}`,
      })
      resetCustomerStore([
        'completeCustomerDraftStatus',
        'completeCustomerDraftData',
      ])
    }

    if (getCustomerDraftQuoteDetailStatus === 'success') {
      if (getCustomerDraftQuoteDetailData.policy_application_id) {
        this.props.history.replace(
          `/customer/policy/${getCustomerDraftQuoteDetailData.policy_application_id}/${this.state.step}/summary`
        )
        return
      }
      const policyDetails = getCustomerDraftQuoteDetailData?.policy_details
      const totalBill =
        policyDetails?.total_bill || policyDetails?.package_data?.total_bill
      const quote = {
        ...policyDetails?.package_data,
        policy_detail: {
          ...policyDetails,
        },
        product: {
          ...policyDetails.package_data,
        },
        premium: {
          period: 12,
          amount: policyDetails?.package_data?.basic_premium,
        },
        discount: policyDetails.discount,
        customer_data: policyDetails?.customer_data,
        total_premium: totalBill,
        draft_id: this.draftQuoteId,
        total_bill: totalBill,
      }
      this.setState({
        policyQuotation: quote,
      })
      resetCustomerStore(['getCustomerDraftQuoteDetailStatus'])
    }
  }

  handleChoosePayment = () => {
    const { customerPolicy } = this.props
    const { tncChecked } = this.state
    const policyId = this.props.match.params.policyId
    const transactionId = get(customerPolicy, 'transaction_ids.customer', '')
    if (tncChecked) {
      if (
        get(customerPolicy, 'status', '') === 'PAYMENT_PENDING' &&
        transactionId
      ) {
        this.props.history.push({
          pathname: `/customer/payment/${customerPolicy?.product_key}/${policyId}`,
        })
      } else if (
        REDIRECT_PAYMENT_STATUS.includes(
          get(customerPolicy, 'payment_status', '')
        )
      ) {
        this.props.history.push(
          `/customer/payment/success/${transactionId}/${policyId}`
        )
      } else {
        if (this.policyId) {
          this.props.submitCustomerPolicy(policyId)
        } else if (this.draftQuoteId) {
          this.props.completeCustomerDraftQuoteReq({
            draftQuoteId: this.draftQuoteId,
          })
        }
      }
    } else {
      this.setState({
        showTncModal: true,
      })
    }
  }

  renderHeader = (head) => {
    return (
      <CustomText
        color={AgentColorPallette.black}
        size="15px"
        weight={800}
        top="8px"
        bottom="0"
      >
        {head}
      </CustomText>
    )
  }

  renderContent = (head, value, color) => {
    return (
      <div className="data">
        <CustomText color={AgentColorPallette.fontGrey} size="14px" top="8px">
          {head}
        </CustomText>
        <CustomText
          color={color || AgentColorPallette.fontDarkerGrey}
          size="14px"
          bottom="8px"
          weight={700}
          top="2px"
          className="break-word-newline"
        >
          {value}
        </CustomText>
      </div>
    )
  }

  renderSingleImgContainer = (title, imgUrl) => {
    return (
      <ZoomImg
        src={imgUrl}
        imgContainer={
          <SingleImgContainer
            minWidth="50px"
            title={title}
            imgUrl={imgUrl}
            titlePosition="up"
            titleAlign="start"
          />
        }
      />
    )
  }

  renderImgTitle = (title, img) => {
    return (
      <ZoomImg
        src={img}
        imgContainer={
          <SingleImgContainer minWidth="50px" imgUrl={img} title={title} />
        }
        imgClassName="width-image"
      />
    )
  }

  renderImagesSection = (imgData = {}) => {
    const { left, right } = imgData
    return (
      <div className="display-flex">
        {this.renderImgTitle(left.title, left.imgUrl)}
        {this.renderImgTitle(right.title, right.imgUrl)}
      </div>
    )
  }

  renderAddonsData = (addonsData = []) => {
    return (
      addonsData.length &&
      addonsData.map((addon) => (
        <Row justify="space-between" key={addon.add_on_code}>
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size="14px"
            bottom="8px"
            weight={700}
          >
            {addon.add_on_name}
          </CustomText>
          <CustomText
            size="14px"
            color={AgentColorPallette.fontDarkerGrey}
            bottom="8px"
          >
            <i className="fa fa-check" />
          </CustomText>
        </Row>
      ))
    )
  }

  renderBenefitExpandData = (title, benefit = {}) => {
    const { data = [] } = benefit
    if (!data.length) return null
    return (
      <div className="data">
        <CustomText color={AgentColorPallette.fontGrey} size="14px" top="8px">
          {title}
        </CustomText>
        <Expand title={data[0].title} className="render-expand">
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size="14px"
            bottom="8px"
            weight={700}
            top="16px"
          >
            {data[0].description}
          </CustomText>
        </Expand>
      </div>
    )
  }

  renderTermsConditionExpandData = (title, terms = {}) => {
    const { data = [] } = terms
    if (!data.length) return null
    return (
      <div className="data">
        <CustomText color={AgentColorPallette.fontGrey} size="14px" top="18px">
          {title}
        </CustomText>
        <Expand title={title} className="render-expand">
          {
            <div className="tnc-content">
              {<TermsCondition termsData={data} />}
            </div>
          }
        </Expand>
      </div>
    )
  }

  getHardcopySentTo = (hardcopySentTo) => {
    switch (hardcopySentTo) {
      case 'send-to-customer':
        return LANG_STRINGS.sendToCustomer
      case 'send-to-agent':
        return LANG_STRINGS.sendToAgent
      case 'send-to-pasarpolis':
        return LANG_STRINGS.sendToPasarpolis
      case 'send-to-another-address':
        return LANG_STRINGS.sendToAnotherAddress
      default:
        return ''
    }
  }

  render() {
    const {
      customerPolicyLoader,
      submitPolicyLoader,
      completeCustomerDraftLoading,
    } = this.props
    const { isValidateTime, step, showTncModal, tncChecked, policyQuotation } =
      this.state

    const {
      product = {},
      policy_detail: policyDetail = {},
      customer_data: customerData = {},
      policy_status: policyStatus,
    } = policyQuotation
    const { images = {}, accessories } = policyDetail
    const { tnc = {}, benefit } = product

    const hardCopyAddress = get(policyDetail, 'hard_copy_address', {})
    const hardCopySentTo = this.getHardcopySentTo(
      get(policyDetail, 'hard_copy_sent_to', '')
    )
    const hardcopyRecipient = get(policyDetail, 'hard_copy_recipient', '')
    const hardcopyMobile = get(policyDetail, 'hard_copy_recipient_mobile', '')
    const isApplicationCancelled = ['CANCELLED', 'REJECTED'].includes(
      policyStatus
    )

    return (
      <Container
        mitraHeader
        hideBottomTabs
        loader={
          customerPolicyLoader ||
          submitPolicyLoader ||
          completeCustomerDraftLoading
        }
      >
        <CustPolicySummaryStyle>
          <PolicyInfo
            remarks={policyQuotation?.insurance_details?.remark_details || {}}
            status={policyQuotation?.policy_status || ''}
            marginTop="18px"
          />
          <StepsHeader
            className={`${isApplicationCancelled ? 'mt-0' : ''}`}
            leftText={LANG_STRINGS.paymentConfirmation}
            current={step}
            totalSteps={step === '1' ? '2' : '4'}
          />
          {isValidateTime && policyQuotation.application_date && (
            <PaymentTime
              time={policyQuotation.application_date}
              className="mt-0"
            />
          )}
          <SummaryBodyStyle>
            {
              <>
                <div className="package-card-container">
                  <QuickViewPackageCard
                    packageLogo={product?.provider?.logo_url}
                    providerName={product?.provider?.name}
                    packageName={product?.name}
                    amount={formatMoney(
                      get(product, 'premium_breakup.base_premium.premium', 0),
                      0
                    )}
                    periodText={LANG_STRINGS.mvPeriod}
                    branch={policyDetail.provider_branch}
                  />
                </div>
              </>
            }
            {
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.transactionDetail)}
                  <hr />
                  {this.renderContent(
                    LANG_STRINGS.paymentStatus,
                    policyQuotation.status || '-'
                  )}
                  {this.renderContent(
                    LANG_STRINGS.transactionDate,
                    moment(policyQuotation.application_date).format(
                      'DD MMMM YYYY'
                    )
                  )}
                </div>
              </>
            }
            {
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.policyDetail)}
                  <hr />
                  {this.renderContent(
                    LANG_STRINGS.policyStatus,
                    policyQuotation.policy_status || '-'
                  )}
                  {this.renderContent(
                    LANG_STRINGS.monthlyPremium,
                    `${formatMoney(policyQuotation.total_premium, 0)}`,
                    AgentColorPallette.mustard
                  )}
                  {this.renderContent(
                    LANG_STRINGS.policyNumber,
                    policyQuotation.application_no || '-'
                  )}
                  {this.renderContent(
                    LANG_STRINGS.protectionPeriod,
                    '12 Bulan'
                  )}
                  {this.renderBenefitExpandData(LANG_STRINGS.benefit, benefit)}
                  {this.renderTermsConditionExpandData(
                    LANG_STRINGS.termsConditions,
                    tnc
                  )}
                </div>
              </>
            }
            {
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.customerData)}
                  <hr />
                  {this.renderSingleImgContainer(
                    LANG_STRINGS.photoKTP,
                    policyDetail.ktp_url
                  )}
                  {policyDetail.ktp_no
                    ? this.renderContent('Nomor KTP', policyDetail.ktp_no)
                    : null}
                  {this.renderContent(
                    `${LANG_STRINGS.fullName} (KTP)`,
                    customerData.name
                  )}
                  {this.renderContent(
                    LANG_STRINGS.customerPhone,
                    customerData.mobile_no
                  )}
                  {this.renderContent(
                    LANG_STRINGS.emailAddress,
                    customerData.email
                  )}
                  {!isEmpty(customerData.customer_address) && (
                    <>
                      {this.renderContent(
                        'Propinsi',
                        customerData.customer_address.province_name
                      )}
                      {this.renderContent(
                        'Kota',
                        customerData.customer_address.city_name
                      )}
                      {this.renderContent(
                        'Kode Pos',
                        customerData.customer_address.postal_code
                      )}
                      {this.renderContent(
                        'Detil Alamat',
                        customerData.customer_address.address
                      )}
                    </>
                  )}
                  {!!customerData.ktp_no &&
                    this.renderContent('KTP', customerData.ktp_no)}
                  {!!customerData.npwp_no &&
                    this.renderContent('NPWP', customerData.npwp_no)}
                </div>
              </>
            }
            {!!policyDetail.previous_certificate_url && (
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.policyCertificate)}
                  <hr />
                  <CustomText
                    color={AgentColorPallette.fontGrey}
                    size="14px"
                    top="8px"
                  >
                    {LANG_STRINGS.policyCertificate}
                  </CustomText>
                  <PdfContainer url={policyDetail.previous_certificate_url} />
                </div>
              </>
            )}
            {!!policyDetail.appointment_letter_url && (
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.otherDocuments)}
                  <hr />
                  <CustomText
                    color={AgentColorPallette.fontGrey}
                    size="14px"
                    top="8px"
                  >
                    {LANG_STRINGS.letterOfAppointment}
                  </CustomText>
                  <PdfContainer url={policyDetail.appointment_letter_url} />
                </div>
              </>
            )}
            {!isEmpty(policyDetail) && (
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.insuredObject)}
                  <hr />
                  {this.renderContent(
                    LANG_STRINGS.benefitType,
                    product.package.name
                  )}
                  {this.renderContent(
                    LANG_STRINGS.transportationType,
                    getVehicleType(policyDetail.vehicle_type)
                  )}
                  {/* {this.renderContent("Seri Kendaraan", policy_detail.variant)} */}
                  {this.renderContent(
                    LANG_STRINGS.productionYear,
                    policyDetail.year
                  )}
                  {this.renderContent(
                    LANG_STRINGS.plateNumber,
                    policyDetail.region_code +
                      ' ' +
                      policyDetail.vehicle_plate_no
                  )}
                  {this.renderContent(
                    LANG_STRINGS.vehicleBrands,
                    policyDetail.brand
                  )}
                  {this.renderContent(
                    LANG_STRINGS.vehicleUse,
                    USAGE[policyDetail.usage]
                  )}
                  {this.renderContent(
                    LANG_STRINGS.vehicleModel,
                    policyDetail.variant
                  )}
                  {this.renderContent(
                    LANG_STRINGS.chassisNumber,
                    policyDetail.chasis_number
                  )}
                  {this.renderContent(
                    LANG_STRINGS.machineNumber,
                    policyDetail.machine_number
                  )}
                  {this.renderContent(
                    LANG_STRINGS.transmission,
                    policyDetail.transmission_type
                  )}
                  {this.renderContent(LANG_STRINGS.color, policyDetail.color)}
                  {this.renderSingleImgContainer(
                    LANG_STRINGS.stnkPhoto,
                    policyDetail.stnk_url
                  )}
                </div>
              </>
            )}
            {!isEmpty(images) && (
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.photoInsuredObject)}
                  <hr />
                  <div
                    className="image-display"
                    style={{ backgroundImage: `url(${images.dashboard})` }}
                  />
                  <CustomText
                    color={AgentColorPallette.fontDarkerGrey}
                    textAlign="center"
                  >
                    {LANG_STRINGS.dashboard}
                  </CustomText>
                  {this.renderImagesSection({
                    left: {
                      imgUrl: images.front,
                      title: LANG_STRINGS.frontLook,
                    },
                    right: {
                      imgUrl: images.back,
                      title: LANG_STRINGS.toTheRightSide,
                    },
                  })}
                  {this.renderImagesSection({
                    left: {
                      imgUrl: images.left,
                      title: LANG_STRINGS.leftSide,
                    },
                    right: {
                      imgUrl: images.right,
                      title: LANG_STRINGS.backView,
                    },
                  })}
                </div>
                <hr />
              </>
            )}
            {policyDetail.hard_copy_required && (
              <>
                <div className="content">
                  {this.renderHeader(LANG_STRINGS.printPolicy)}
                  <hr />
                  {this.renderContent(
                    LANG_STRINGS.shippingOption,
                    hardCopySentTo
                  )}
                  {this.renderContent(
                    LANG_STRINGS.province,
                    hardCopyAddress.province_name
                  )}
                  {this.renderContent(
                    LANG_STRINGS.city,
                    hardCopyAddress.city_name
                  )}
                  {this.renderContent(
                    LANG_STRINGS.postalCode,
                    hardCopyAddress.postal_code
                  )}
                  {this.renderContent(
                    LANG_STRINGS.address,
                    hardCopyAddress.address
                  )}
                  {hardcopyRecipient &&
                    this.renderContent(
                      LANG_STRINGS.recipientName,
                      hardcopyRecipient
                    )}
                  {hardcopyMobile &&
                    this.renderContent(
                      LANG_STRINGS.activeMobileNumber,
                      hardcopyMobile
                    )}
                </div>
              </>
            )}
            {!!(accessories && accessories.length > 0) && (
              <div className="content">
                {this.renderHeader(
                  `${accessories.length > 0 ? '4. ' : '3. '} Aksesoris Tambahan`
                )}
                <hr />
                {accessories.map((accessory, index) => (
                  <div className="accessory-data" key={`accessory_${index}`}>
                    <img
                      src={accessory.img}
                      alt="accessory-img"
                      className="accessory-image"
                    />
                    <div className="accessory-right-section">
                      <CustomText
                        color={AgentColorPallette.fontGrey}
                        size="14px"
                        top="8px"
                      >
                        {LANG_STRINGS.accessoriesType}
                      </CustomText>
                      <CustomText
                        color={AgentColorPallette.fontDarkerGrey}
                        size="14px"
                        bottom="8px"
                        weight={700}
                        top="2px"
                      >
                        {ACCESSORY[accessory.accessory_type]}
                      </CustomText>
                      <CustomText
                        color={AgentColorPallette.fontGrey}
                        size="14px"
                        top="8px"
                      >
                        Nama Aksesoris
                      </CustomText>
                      <CustomText
                        color={AgentColorPallette.fontDarkerGrey}
                        size="14px"
                        bottom="8px"
                        weight={700}
                        top="2px"
                      >
                        {accessory.name}
                      </CustomText>
                      <CustomText
                        color={AgentColorPallette.fontGrey}
                        size="14px"
                        top="8px"
                      >
                        Harga Aksesoris
                      </CustomText>
                      <CustomText
                        color={AgentColorPallette.fontDarkerGrey}
                        size="14px"
                        bottom="8px"
                        weight={700}
                        top="2px"
                      >
                        {accessory.sum_insured}
                      </CustomText>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {!!(!isEmpty(product) && product.add_ons?.length) && (
              <div className="content">
                {this.renderHeader(LANG_STRINGS.supplementalLiability)}
                <hr />
                {this.renderAddonsData(product.add_ons)}
              </div>
            )}
          </SummaryBodyStyle>
          <PolicyAmountDistribution
            pkgDetail={{
              ...policyDetail,
              ...product,
              admin_fee: policyQuotation?.admin_fee,
            }}
            isShowTermsNConditions
            discount={policyDetail.discount || policyQuotation.discount}
            hideDiscount={!(policyDetail.discount || policyQuotation.discount)}
            position="relative !important"
            onChoosePayment={this.handleChoosePayment}
            id="customer-summary"
            hidePaymentBtn={isApplicationCancelled}
            tncChecked={tncChecked}
            onTnCClick={() =>
              this.setState({
                showTncModal: true,
              })
            }
          />
          {showTncModal && (
            <TermsNConditionModal
              isOpen={showTncModal}
              tncData={tnc.data}
              onAccept={() => {
                this.setState({ showTncModal: false, tncChecked: true })
              }}
              onReject={() =>
                this.setState({ showTncModal: false, tncChecked: false })
              }
            />
          )}
        </CustPolicySummaryStyle>
        <NotificationContainer />
      </Container>
    )
  }
}

export default connect(
  (state) => ({
    customerPolicy: state.Customer.customerPolicyData,
    customerPolicyDataStatus: state.Customer.customerPolicyDataStatus,
    submitCustomerPolicyData: state.Customer.submitCustomerPolicyData,
    submitCustomerPolicyStatus: state.Customer.submitCustomerPolicyStatus,
    submitPolicyLoader: state.Loading.SUBMIT_CUSTOMER_POLICY,
    customerPolicyLoader: state.Loading.GET_CUSTOMER_POLICY,
    completeCustomerDraftStatus: state.Customer.completeCustomerDraftStatus,
    completeCustomerDraftData: state.Customer.completeCustomerDraftData,
    completeCustomerDraftLoading: state.Loading.COMPLETE_CUSTOMER_DRAFT,
    getCustomerDraftQuoteDetailData:
      state.Customer.getCustomerDraftQuoteDetailData,
    getCustomerDraftQuoteDetailLoading:
      state.Loading.GET_CUSTOMER_DRAFT_QUOTE_DETAIL,
    getCustomerDraftQuoteDetailStatus:
      state.Customer.getCustomerDraftQuoteDetailStatus,
    submitPolicyError: state.Error.SUBMIT_CUSTOMER_POLICY,
    customerError: state.Error.GET_CUSTOMER_POLICY,
  }),
  {
    getCustomerPolicy,
    submitCustomerPolicy,
    getCustomerDraftDetailsReq,
    completeCustomerDraftQuoteReq,
    resetCustomerStore,
  }
)(CustomerPolicySummary)
