import { Component } from 'react'
import PropTypes from 'prop-types'
import { PaymentTimeStyle } from './index.style'
import { CustomText } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { Row, DisplayFlexCCC } from '../../../../../../commonStyle/index.style'
import { prefixZero } from '../../../../../../helpers/utility'
import { PAYMENT_HOURS } from '../../../../../../constants/payment'

class PaymentTime extends Component {
  static propTypes = {
    time: PropTypes.string,
    paymentDays: PropTypes.number, // represent : 60 => 59, 90 => 89
  }

  constructor(props) {
    super(props)
    this.state = {
      days: props.paymentDays, // represent number of days left for the payment from the initiated date
      hour: 0,
      minute: 0,
      second: 0,
    }
    let paymentHours = props.paymentHours
    if (!paymentHours) {
      paymentHours = PAYMENT_HOURS
    }
    this.clearInterval = ''
    this.endDateString = new Date(
      new Date(props.expiryDate).getTime()
    ).toDateString()
  }

  componentDidMount() {
    this.getTimeCounter()
  }

  componentWillUnmount() {
    // clear interval as component unmount
    clearInterval(this.clearInterval)
  }

  getTimeCounter = () => {
    const { time, expiryDate } = this.props
    const endDateTime = new Date(expiryDate)

    function updateClock() {
      const now = new Date()
      let diff = Math.round((endDateTime.getTime() - now.getTime()) / 1000) // seconds remaining

      if (diff < 0) diff = 0

      const d = Math.floor(diff / (24 * 60 * 60))
      diff = diff - d * 24 * 60 * 60
      const h = Math.floor(diff / (60 * 60))
      diff = diff - h * 60 * 60
      const m = Math.floor(diff / 60)
      diff = diff - m * 60
      const s = diff

      return {
        d,
        h: prefixZero(h),
        m: prefixZero(m),
        s: prefixZero(s),
      }
    }

    this.clearInterval = setInterval(() => {
      const { d, h, m, s } = updateClock()
      this.setState({
        days: d,
        hour: h,
        minute: m,
        second: s,
      })
    }, 1000)
  }

  getTimeContainer = (title, value) => {
    return (
      <DisplayFlexCCC className="payment-time-box">
        <CustomText
          color={AgentColorPallette.black}
          size="26px"
          bottom="1px"
          weight={800}
        >
          {value}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontSemiGrey}
          size="10px"
          weight={800}
        >
          {title}
        </CustomText>
      </DisplayFlexCCC>
    )
  }

  render() {
    const { days, hour, minute, second } = this.state
    const { className, scenario = 'default' } = this.props

    if (scenario === 'inline') {
      return (
        <CustomText
          color={AgentColorPallette.white}
          size="10px"
          bottom="0"
          weight={800}
        >
          {`${days > 0 ? `${days}D : ` : ''}${hour}H : ${minute}M : ${second}S`}
        </CustomText>
      )
    } else {
      return (
        <PaymentTimeStyle className={className}>
          <CustomText color={AgentColorPallette.black} size="10px" weight={800}>
            {LANG_STRINGS.remainingPaymentTime}
          </CustomText>
          <Row justify="space-between" className="timing-container">
            {this.getTimeContainer(LANG_STRINGS.hour, hour)}
            {this.getTimeContainer(LANG_STRINGS.minute, minute)}
            {this.getTimeContainer(LANG_STRINGS.second, second)}
          </Row>
        </PaymentTimeStyle>
      )
    }
  }
}

export default PaymentTime
